20	import PointerPath from './PointerPath';
21	import * as graphic from '../../util/graphic';
22	import { setStatesStylesFromModel, toggleHoverEmphasis } from '../../util/states';
23	import {createTextStyle, setLabelValueAnimation, animateLabelValue} from '../../label/labelStyle';
24	import ChartView from '../../view/Chart';
25	import {parsePercent, round, linearMap} from '../../util/number';
26	import GaugeSeriesModel, { GaugeDataItemOption } from './GaugeSeries';
27	import GlobalModel from '../../model/Global';
28	import ExtensionAPI from '../../core/ExtensionAPI';
29	import { ColorString, ECElement } from '../../util/types';
30	import SeriesData from '../../data/SeriesData';
31	import Sausage from '../../util/shape/sausage';
32	import {createSymbol} from '../../util/symbol';
33	import ZRImage from 'zrender/src/graphic/Image';
34	import { extend, isFunction, isString, isNumber, each } from 'zrender/src/core/util';
35	import {setCommonECData} from '../../util/innerStore';
36	import { normalizeArcAngles } from 'zrender/src/core/PathProxy';
37	
38	type ECSymbol = ReturnType<typeof createSymbol>;
39	
40	interface PosInfo {
41	    cx: number
42	    cy: number
43	    r: number
44	}
45	
46	function parsePosition(seriesModel: GaugeSeriesModel, api: ExtensionAPI): PosInfo {
47	    const center = seriesModel.get('center');
48	    const width = api.getWidth();
49	    const height = api.getHeight();
50	    const size = Math.min(width, height);
51	    const cx = parsePercent(center[0], api.getWidth());
52	    const cy = parsePercent(center[1], api.getHeight());
53	    const r = parsePercent(seriesModel.get('radius'), size / 2);
54	
55	    return {
56	        cx: cx,
57	        cy: cy,
58	        r: r
59	    };
60	}
61	
62	function formatLabel(value: number, labelFormatter: string | ((value: number) => string)): string {
63	    let label = value == null ? '' : (value + '');
64	    if (labelFormatter) {
65	        if (isString(labelFormatter)) {
66	            label = labelFormatter.replace('{value}', label);
67	        }
68	        else if (isFunction(labelFormatter)) {
69	            label = labelFormatter(value);
70	        }
71	    }
72	
73	    return label;
74	}
75	
76	class GaugeView extends ChartView {
77	    static type = 'gauge' as const;
78	    type = GaugeView.type;
79	
80	    private _data: SeriesData;
81	    private _progressEls: graphic.Path[];
82	
83	    private _titleEls: graphic.Text[];
84	    private _detailEls: graphic.Text[];
85	
86	    render(seriesModel: GaugeSeriesModel, ecModel: GlobalModel, api: ExtensionAPI) {
87	
88	        this.group.removeAll();
89	
90	        const colorList = seriesModel.get(['axisLine', 'lineStyle', 'color']);
91	        const posInfo = parsePosition(seriesModel, api);
92	
93	        this._renderMain(
94	            seriesModel, ecModel, api, colorList, posInfo
95	        );
96	
97	        this._data = seriesModel.getData();
98	    }
99	
100	    dispose() {}
101	
102	    _renderMain(
103	        seriesModel: GaugeSeriesModel,
104	        ecModel: GlobalModel,
105	        api: ExtensionAPI,
106	        colorList: [number, ColorString][],
107	        posInfo: PosInfo
108	    ) {
109	        const group = this.group;
110	        const clockwise = seriesModel.get('clockwise');
111	        let startAngle = -seriesModel.get('startAngle') / 180 * Math.PI;
112	        let endAngle = -seriesModel.get('endAngle') / 180 * Math.PI;
113	        const axisLineModel = seriesModel.getModel('axisLine');
114	
115	        const roundCap = axisLineModel.get('roundCap');
116	        const MainPath = roundCap ? Sausage : graphic.Sector;
117	
118	        const showAxis = axisLineModel.get('show');
119	        const lineStyleModel = axisLineModel.getModel('lineStyle');
120	        const axisLineWidth = lineStyleModel.get('width');
121	
122	        const angles = [startAngle, endAngle];
123	        normalizeArcAngles(angles, !clockwise);
124	        startAngle = angles[0];
125	        endAngle = angles[1];
126	        const angleRangeSpan = endAngle - startAngle;
127	
128	        let prevEndAngle = startAngle;
129	
130	        const sectors: (Sausage | graphic.Sector)[] = [];
131	        for (let i = 0; showAxis && i < colorList.length; i++) {
132	            // Clamp
133	            const percent = Math.min(Math.max(colorList[i][0], 0), 1);
134	            endAngle = startAngle + angleRangeSpan * percent;
135	            const sector = new MainPath({
136	                shape: {
137	                    startAngle: prevEndAngle,
138	                    endAngle: endAngle,
139	                    cx: posInfo.cx,
140	                    cy: posInfo.cy,
141	                    clockwise: clockwise,
142	                    r0: posInfo.r - axisLineWidth,
143	                    r: posInfo.r
144	                },
145	                silent: true
146	            });
147	
148	            sector.setStyle({
149	                fill: colorList[i][1]
150	            });
151	
152	            sector.setStyle(lineStyleModel.getLineStyle(
153	                // Because we use sector to simulate arc
154	                // so the properties for stroking are useless
155	                ['color', 'width']
156	            ));
157	
158	            sectors.push(sector);
159	
160	            prevEndAngle = endAngle;
161	        }
162	
163	        sectors.reverse();
164	        each(sectors, sector => group.add(sector));
165	
166	        const getColor = function (percent: number) {
167	            // Less than 0
168	            if (percent <= 0) {
169	                return colorList[0][1];
170	            }
171	            let i;
172	            for (i = 0; i < colorList.length; i++) {
173	                if (colorList[i][0] >= percent
174	                    && (i === 0 ? 0 : colorList[i - 1][0]) < percent
175	                ) {
176	                    return colorList[i][1];
177	                }
178	            }
179	            // More than 1
180	            return colorList[i - 1][1];
181	        };
182	
183	        this._renderTicks(
184	            seriesModel, ecModel, api, getColor, posInfo,
185	            startAngle, endAngle, clockwise, axisLineWidth
186	        );
187	
188	        this._renderTitleAndDetail(
189	            seriesModel, ecModel, api, getColor, posInfo
190	        );
191	
192	        this._renderAnchor(seriesModel, posInfo);
193	
194	        this._renderPointer(
195	            seriesModel, ecModel, api, getColor, posInfo,
196	            startAngle, endAngle, clockwise, axisLineWidth
197	        );
198	    }
199	
200	    _renderTicks(
201	        seriesModel: GaugeSeriesModel,
202	        ecModel: GlobalModel,
203	        api: ExtensionAPI,
204	        getColor: (percent: number) => ColorString,
205	        posInfo: PosInfo,
206	        startAngle: number,
207	        endAngle: number,
208	        clockwise: boolean,
209	        axisLineWidth: number
210	    ) {
211	        const group = this.group;
212	        const cx = posInfo.cx;
213	        const cy = posInfo.cy;
214	        const r = posInfo.r;
215	
216	        const minVal = +seriesModel.get('min');
217	        const maxVal = +seriesModel.get('max');
218	
219	        const splitLineModel = seriesModel.getModel('splitLine');
220	        const tickModel = seriesModel.getModel('axisTick');
221	        const labelModel = seriesModel.getModel('axisLabel');
222	
223	        const splitNumber = seriesModel.get('splitNumber');
224	        const subSplitNumber = tickModel.get('splitNumber');
225	
226	        const splitLineLen = parsePercent(
227	            splitLineModel.get('length'), r
228	        );
229	        const tickLen = parsePercent(
230	            tickModel.get('length'), r
231	        );
232	
233	        let angle = startAngle;
234	        const step = (endAngle - startAngle) / splitNumber;
235	        const subStep = step / subSplitNumber;
236	
237	        const splitLineStyle = splitLineModel.getModel('lineStyle').getLineStyle();
238	        const tickLineStyle = tickModel.getModel('lineStyle').getLineStyle();
239	
240	        const splitLineDistance = splitLineModel.get('distance');
241	
242	        let unitX;
243	        let unitY;
244	
245	        for (let i = 0; i <= splitNumber; i++) {
246	            unitX = Math.cos(angle);
247	            unitY = Math.sin(angle);
248	            // Split line
249	            if (splitLineModel.get('show')) {
250	                const distance = splitLineDistance ? splitLineDistance + axisLineWidth : axisLineWidth;
251	                const splitLine = new graphic.Line({
252	                    shape: {
253	                        x1: unitX * (r - distance) + cx,
254	                        y1: unitY * (r - distance) + cy,
255	                        x2: unitX * (r - splitLineLen - distance) + cx,
256	                        y2: unitY * (r - splitLineLen - distance) + cy
257	                    },
258	                    style: splitLineStyle,
259	                    silent: true
260	                });
261	                if (splitLineStyle.stroke === 'auto') {
262	                    splitLine.setStyle({
263	                        stroke: getColor(i / splitNumber)
264	                    });
265	                }
266	
267	                group.add(splitLine);
268	            }
269	
270	            // Label
271	            if (labelModel.get('show')) {
272	                const distance = labelModel.get('distance') + splitLineDistance;
273	
274	                const label = formatLabel(
275	                    round(i / splitNumber * (maxVal - minVal) + minVal),
276	                    labelModel.get('formatter')
277	                );
278	                const autoColor = getColor(i / splitNumber);
279	                const textStyleX = unitX * (r - splitLineLen - distance) + cx;
280	                const textStyleY = unitY * (r - splitLineLen - distance) + cy;
281	
282	                const rotateType = labelModel.get('rotate');
283	                let rotate = 0;
284	                if (rotateType === 'radial') {
285	                    rotate = -angle + 2 * Math.PI;
286	                    if (rotate > Math.PI / 2) {
287	                        rotate += Math.PI;
288	                    }
289	                }
290	                else if (rotateType === 'tangential') {
291	                    rotate = -angle - Math.PI / 2;
292	                }
293	                else if (isNumber(rotateType)) {
294	                    rotate = rotateType * Math.PI / 180;
295	                }
296	
297	                if (rotate === 0) {
298	                    group.add(new graphic.Text({
299	                        style: createTextStyle(labelModel, {
300	                            text: label,
301	                            x: textStyleX,
302	                            y: textStyleY,
303	                            verticalAlign: unitY < -0.8 ? 'top' : (unitY > 0.8 ? 'bottom' : 'middle'),
304	                            align: unitX < -0.4 ? 'left' : (unitX > 0.4 ? 'right' : 'center')
305	                        }, {
306	                            inheritColor: autoColor
307	                        }),
308	                        silent: true
309	                    }));
310	                }
311	                else {
312	                    group.add(new graphic.Text({
313	                        style: createTextStyle(labelModel, {
314	                            text: label,
315	                            x: textStyleX,
316	                            y: textStyleY,
317	                            verticalAlign: 'middle',
318	                            align: 'center'
319	                        }, {
320	                            inheritColor: autoColor
321	                        }),
322	                        silent: true,
323	                        originX: textStyleX,
324	                        originY: textStyleY,
325	                        rotation: rotate
326	                    }));
327	                }
328	            }
329	
330	            // Axis tick
331	            if (tickModel.get('show') && i !== splitNumber) {
332	                let distance = tickModel.get('distance');
333	                distance = distance ? distance + axisLineWidth : axisLineWidth;
334	
335	                for (let j = 0; j <= subSplitNumber; j++) {
336	                    unitX = Math.cos(angle);
337	                    unitY = Math.sin(angle);
338	                    const tickLine = new graphic.Line({
339	                        shape: {
340	                            x1: unitX * (r - distance) + cx,
341	                            y1: unitY * (r - distance) + cy,
342	                            x2: unitX * (r - tickLen - distance) + cx,
343	                            y2: unitY * (r - tickLen - distance) + cy
344	                        },
345	                        silent: true,
346	                        style: tickLineStyle
347	                    });
348	
349	                    if (tickLineStyle.stroke === 'auto') {
350	                        tickLine.setStyle({
351	                            stroke: getColor((i + j / subSplitNumber) / splitNumber)
352	                        });
353	                    }
354	
355	                    group.add(tickLine);
356	                    angle += subStep;
357	                }
358	                angle -= subStep;
359	            }
360	            else {
361	                angle += step;
362	            }
363	        }
364	    }
365	
366	    _renderPointer(
367	        seriesModel: GaugeSeriesModel,
368	        ecModel: GlobalModel,
369	        api: ExtensionAPI,
370	        getColor: (percent: number) => ColorString,
371	        posInfo: PosInfo,
372	        startAngle: number,
373	        endAngle: number,
374	        clockwise: boolean,
375	        axisLineWidth: number
376	    ) {
377	
378	        const group = this.group;
379	        const oldData = this._data;
380	        const oldProgressData = this._progressEls;
381	        const progressList = [] as graphic.Path[];
382	
383	        const showPointer = seriesModel.get(['pointer', 'show']);
384	        const progressModel = seriesModel.getModel('progress');
385	        const showProgress = progressModel.get('show');
386	
387	        const data = seriesModel.getData();
388	        const valueDim = data.mapDimension('value');
389	        const minVal = +seriesModel.get('min');
390	        const maxVal = +seriesModel.get('max');
391	        const valueExtent = [minVal, maxVal];
392	        const angleExtent = [startAngle, endAngle];
393	
394	        function createPointer(idx: number, angle: number) {
395	            const itemModel = data.getItemModel<GaugeDataItemOption>(idx);
396	            const pointerModel = itemModel.getModel('pointer');
397	            const pointerWidth = parsePercent(pointerModel.get('width'), posInfo.r);
398	            const pointerLength = parsePercent(pointerModel.get('length'), posInfo.r);
399	            const pointerStr = seriesModel.get(['pointer', 'icon']);
400	            const pointerOffset = pointerModel.get('offsetCenter');
401	            const pointerOffsetX = parsePercent(pointerOffset[0], posInfo.r);
402	            const pointerOffsetY = parsePercent(pointerOffset[1], posInfo.r);
403	            const pointerKeepAspect = pointerModel.get('keepAspect');
404	
405	            let pointer;
406	            // not exist icon type will be set 'rect'
407	            if (pointerStr) {
408	                pointer = createSymbol(
409	                    pointerStr,
410	                    pointerOffsetX - pointerWidth / 2,
411	                    pointerOffsetY - pointerLength,
412	                    pointerWidth,
413	                    pointerLength,
414	                    null,
415	                    pointerKeepAspect
416	                ) as graphic.Path;
417	            }
418	            else {
419	                pointer = new PointerPath({
420	                    shape: {
421	                        angle: -Math.PI / 2,
422	                        width: pointerWidth,
423	                        r: pointerLength,
424	                        x: pointerOffsetX,
425	                        y: pointerOffsetY
426	                    }
427	                });
428	            }
429	            pointer.rotation = -(angle + Math.PI / 2);
430	            pointer.x = posInfo.cx;
431	            pointer.y = posInfo.cy;
432	            return pointer;
433	        }
434	
435	        function createProgress(idx: number, endAngle: number) {
436	            const roundCap = progressModel.get('roundCap');
437	            const ProgressPath = roundCap ? Sausage : graphic.Sector;
438	
439	            const isOverlap = progressModel.get('overlap');
440	            const progressWidth = isOverlap ? progressModel.get('width') : axisLineWidth / data.count();
441	            const r0 = isOverlap ? posInfo.r - progressWidth : posInfo.r - (idx + 1) * progressWidth;
442	            const r = isOverlap ? posInfo.r : posInfo.r - idx * progressWidth;
443	            const progress = new ProgressPath({
444	                shape: {
445	                    startAngle: startAngle,
446	                    endAngle: endAngle,
447	                    cx: posInfo.cx,
448	                    cy: posInfo.cy,
449	                    clockwise: clockwise,
450	                    r0: r0,
451	                    r: r
452	                }
453	            });
454	            isOverlap && (progress.z2 = linearMap(data.get(valueDim, idx) as number, [minVal, maxVal], [100, 0], true));
455	            return progress;
456	        }
457	
458	        if (showProgress || showPointer) {
459	            data.diff(oldData)
460	                .add(function (idx) {
461	                    const val = data.get(valueDim, idx) as number;
462	                    if (showPointer) {
463	                        const pointer = createPointer(idx, startAngle);
464	                        // TODO hide pointer on NaN value?
465	                        graphic.initProps(pointer, {
466	                            rotation: -(
467	                                (isNaN(+val) ? angleExtent[0] : linearMap(val, valueExtent, angleExtent, true))
468	                                + Math.PI / 2
469	                            )
470	                        }, seriesModel);
471	                        group.add(pointer);
472	                        data.setItemGraphicEl(idx, pointer);
473	                    }
474	
475	                    if (showProgress) {
476	                        const progress = createProgress(idx, startAngle) as graphic.Sector;
477	                        const isClip = progressModel.get('clip');
478	                        graphic.initProps(progress, {
479	                            shape: {
480	                                endAngle: linearMap(val, valueExtent, angleExtent, isClip)
481	                            }
482	                        }, seriesModel);
483	                        group.add(progress);
484	                        // Add data index and series index for indexing the data by element
485	                        // Useful in tooltip
486	                        setCommonECData(seriesModel.seriesIndex, data.dataType, idx, progress);
487	                        progressList[idx] = progress;
488	                    }
489	                })
490	                .update(function (newIdx, oldIdx) {
491	                    const val = data.get(valueDim, newIdx) as number;
492	                    if (showPointer) {
493	                        const previousPointer = oldData.getItemGraphicEl(oldIdx) as PointerPath;
494	                        const previousRotate = previousPointer ? previousPointer.rotation : startAngle;
495	                        const pointer = createPointer(newIdx, previousRotate);
496	                        pointer.rotation = previousRotate;
497	                        graphic.updateProps(pointer, {
498	                            rotation: -(
499	                                (isNaN(+val) ? angleExtent[0] : linearMap(val, valueExtent, angleExtent, true))
500	                                    + Math.PI / 2
501	                            )
502	                        }, seriesModel);
503	                        group.add(pointer);
504	                        data.setItemGraphicEl(newIdx, pointer);
505	                    }
506	
507	                    if (showProgress) {
508	                        const previousProgress = oldProgressData[oldIdx];
509	                        const previousEndAngle = previousProgress ? previousProgress.shape.endAngle : startAngle;
510	                        const progress = createProgress(newIdx, previousEndAngle) as graphic.Sector;
511	                        const isClip = progressModel.get('clip');
512	                        graphic.updateProps(progress, {
513	                            shape: {
514	                                endAngle: linearMap(val, valueExtent, angleExtent, isClip)
515	                            }
516	                        }, seriesModel);
517	                        group.add(progress);
518	                        // Add data index and series index for indexing the data by element
519	                        // Useful in tooltip
520	                        setCommonECData(seriesModel.seriesIndex, data.dataType, newIdx, progress);
521	                        progressList[newIdx] = progress;
522	                    }
523	                })
524	                .execute();
525	
526	            data.each(function (idx) {
527	                const itemModel = data.getItemModel<GaugeDataItemOption>(idx);
528	                const emphasisModel = itemModel.getModel('emphasis');
529	                const focus = emphasisModel.get('focus');
530	                const blurScope = emphasisModel.get('blurScope');
531	                const emphasisDisabled = emphasisModel.get('disabled');
532	                if (showPointer) {
533	                    const pointer = data.getItemGraphicEl(idx) as ECSymbol;
534	                    const symbolStyle = data.getItemVisual(idx, 'style');
535	                    const visualColor = symbolStyle.fill;
536	                    if (pointer instanceof ZRImage) {
537	                        const pathStyle = pointer.style;
538	                        pointer.useStyle(extend({
539	                            image: pathStyle.image,
540	                            x: pathStyle.x, y: pathStyle.y,
541	                            width: pathStyle.width, height: pathStyle.height
542	                        }, symbolStyle));
543	                    }
544	                    else {
545	                        pointer.useStyle(symbolStyle);
546	                        pointer.type !== 'pointer' && pointer.setColor(visualColor);
547	                    }
548	
549	                    pointer.setStyle(itemModel.getModel(['pointer', 'itemStyle']).getItemStyle());
550	
551	
552	                    if (pointer.style.fill === 'auto') {
553	                        pointer.setStyle('fill', getColor(
554	                            linearMap(data.get(valueDim, idx) as number, valueExtent, [0, 1], true)
555	                        ));
556	                    }
557	
558	                    (pointer as ECElement).z2EmphasisLift = 0;
559	                    setStatesStylesFromModel(pointer, itemModel);
560	                    toggleHoverEmphasis(pointer, focus, blurScope, emphasisDisabled);
561	                }
562	
563	                if (showProgress) {
564	                    const progress = progressList[idx];
565	                    progress.useStyle(data.getItemVisual(idx, 'style'));
566	                    progress.setStyle(itemModel.getModel(['progress', 'itemStyle']).getItemStyle());
567	                    (progress as ECElement).z2EmphasisLift = 0;
568	                    setStatesStylesFromModel(progress, itemModel);
569	                    toggleHoverEmphasis(progress, focus, blurScope, emphasisDisabled);
570	                }
571	            });
572	
573	            this._progressEls = progressList;
574	        }
575	    }
576	
577	    _renderAnchor(
578	        seriesModel: GaugeSeriesModel,
579	        posInfo: PosInfo
580	    ) {
581	        const anchorModel = seriesModel.getModel('anchor');
582	        const showAnchor = anchorModel.get('show');
583	        if (showAnchor) {
584	            const anchorSize = anchorModel.get('size');
585	            const anchorType = anchorModel.get('icon');
586	            const offsetCenter = anchorModel.get('offsetCenter');
587	            const anchorKeepAspect = anchorModel.get('keepAspect');
588	            const anchor = createSymbol(
589	                anchorType,
590	                posInfo.cx - anchorSize / 2 + parsePercent(offsetCenter[0], posInfo.r),
591	                posInfo.cy - anchorSize / 2 + parsePercent(offsetCenter[1], posInfo.r),
592	                anchorSize,
593	                anchorSize,
594	                null,
595	                anchorKeepAspect
596	            ) as graphic.Path;
597	            anchor.z2 = anchorModel.get('showAbove') ? 1 : 0;
598	            anchor.setStyle(anchorModel.getModel('itemStyle').getItemStyle());
599	            this.group.add(anchor);
600	        }
601	    }
602	
603	    _renderTitleAndDetail(
604	        seriesModel: GaugeSeriesModel,
605	        ecModel: GlobalModel,
606	        api: ExtensionAPI,
607	        getColor: (percent: number) => ColorString,
608	        posInfo: PosInfo
609	    ) {
610	        const data = seriesModel.getData();
611	        const valueDim = data.mapDimension('value');
612	        const minVal = +seriesModel.get('min');
613	        const maxVal = +seriesModel.get('max');
614	
615	        const contentGroup = new graphic.Group();
616	
617	        const newTitleEls: graphic.Text[] = [];
618	        const newDetailEls: graphic.Text[] = [];
619	        const hasAnimation = seriesModel.isAnimationEnabled();
620	
621	        const showPointerAbove = seriesModel.get(['pointer', 'showAbove']);
622	
623	        data.diff(this._data)
624	            .add((idx) => {
625	                newTitleEls[idx] = new graphic.Text({
626	                    silent: true
627	                });
628	                newDetailEls[idx] = new graphic.Text({
629	                    silent: true
630	                });
631	            })
632	            .update((idx, oldIdx) => {
633	                newTitleEls[idx] = this._titleEls[oldIdx];
634	                newDetailEls[idx] = this._detailEls[oldIdx];
635	            })
636	            .execute();
637	
638	        data.each(function (idx) {
639	            const itemModel = data.getItemModel<GaugeDataItemOption>(idx);
640	            const value = data.get(valueDim, idx) as number;
641	            const itemGroup = new graphic.Group();
642	            const autoColor = getColor(
643	                linearMap(value, [minVal, maxVal], [0, 1], true)
644	            );
645	
646	            const itemTitleModel = itemModel.getModel('title');
647	            if (itemTitleModel.get('show')) {
648	                const titleOffsetCenter = itemTitleModel.get('offsetCenter');
